import { CARD_PATH_CHANGED_EVENT, dataService, type CardPathChangedEventDetail, type DataService } from '../data/data_service'
import { register } from '../service_injector'

export type WorkspaceViewMode = 'cards' | 'diagrams' | 'stats' | 'text'

export interface WorkspaceViewSnapshot {
    selectedPath: string | null
    viewMode: WorkspaceViewMode
}

const INITIAL_SNAPSHOT: WorkspaceViewSnapshot = { selectedPath: null, viewMode: 'cards' }

/** Shared UI state for the project workspace view mode and selected card/file path. */
export class WorkspaceViewService extends EventTarget {
    private projectKey: string | null = null
    private snapshot = INITIAL_SNAPSHOT
    private readonly dataService: DataService

    constructor(dataServiceInstance: DataService) {
        super()
        this.dataService = dataServiceInstance
        this.projectKey = this.currentProjectKey()
        this.dataService.addEventListener('changed', this.handleDataServiceChanged)
        this.dataService.addEventListener(CARD_PATH_CHANGED_EVENT, this.handleCardPathChanged)
    }

    getSnapshot(): WorkspaceViewSnapshot {
        return this.snapshot
    }

    selectPath(path: string) {
        if (!path) throw new Error('Cannot select a workspace path without a path')

        this.update({ ...this.snapshot, selectedPath: path })
    }

    clearSelectedPath(path: string) {
        if (this.snapshot.selectedPath !== path) return

        this.update({ ...this.snapshot, selectedPath: null })
    }

    private readonly handleCardPathChanged = (event: Event) => {
        const { fromPath, toPath } = (event as CustomEvent<CardPathChangedEventDetail>).detail
        if (this.snapshot.selectedPath !== fromPath) return

        this.update({ ...this.snapshot, selectedPath: toPath })
    }

    private readonly handleDataServiceChanged = () => {
        this.syncProject(this.currentProjectKey())
    }

    private syncProject(projectKey: string | null) {
        if (this.projectKey === projectKey) return

        this.projectKey = projectKey
        this.update(INITIAL_SNAPSHOT)
    }

    private currentProjectKey(): string | null {
        const { project } = this.dataService.getState()
        if (!project) return null

        return `${project.id}:${project.branch}`
    }

    setViewMode(viewMode: WorkspaceViewMode) {
        this.update({ ...this.snapshot, viewMode })
    }

    private update(snapshot: WorkspaceViewSnapshot) {
        if (snapshot.selectedPath === this.snapshot.selectedPath && snapshot.viewMode === this.snapshot.viewMode) return

        this.snapshot = snapshot
        this.dispatchEvent(new CustomEvent<WorkspaceViewSnapshot>('changed', { detail: snapshot }))
    }
}

export const workspaceViewService = register('workspaceViewService', new WorkspaceViewService(dataService))

import type { StorageService } from '../../data/data_types'

const SAVE_STATE_EVENT = 'changed'
const STORAGE_SAVE_METHODS = new Set<PropertyKey>([
    'addWorktree',
    'cancelActionSchedule',
    'commit',
    'createProject',
    'deleteFile',
    'deleteFolder',
    'integrateWorktree',
    'moveFiles',
    'removeWorktree',
    'saveActionSchedules',
    'saveProjectConfig',
])

export interface SaveState {
    isSaving: boolean
}

/** Tracks active local persistence operations for global UI state. */
export class SaveStateService extends EventTarget {
    private activeSaveCount = 0
    private readonly activeSaveOperations = new Set<Promise<unknown>>()

    beginSave() {
        this.activeSaveCount += 1
        if (this.activeSaveCount === 1) this.dispatchChanged()

        let finished = false

        return () => {
            if (finished) return
            finished = true
            this.activeSaveCount -= 1
            if (this.activeSaveCount === 0) this.dispatchChanged()
        }
    }

    getState(): SaveState {
        return { isSaving: this.activeSaveCount > 0 }
    }

    async track<T>(operation: () => Promise<T>): Promise<T> {
        const finish = this.beginSave()
        const operationPromise = operation()
        this.activeSaveOperations.add(operationPromise)

        try {
            return await operationPromise
        } finally {
            this.activeSaveOperations.delete(operationPromise)
            finish()
        }
    }

    async drain() {
        while (this.activeSaveOperations.size > 0) {
            await Promise.all([...this.activeSaveOperations])
        }
    }

    private dispatchChanged() {
        this.dispatchEvent(new CustomEvent<SaveState>(SAVE_STATE_EVENT, { detail: this.getState() }))
    }
}

/** Wrap storage mutations so every persisted project change contributes to save state. */
export function withSaveStateTracking(storage: StorageService, saveStateService: SaveStateService): StorageService {
    return new Proxy(storage, {
        get(target, property, receiver) {
            const value: unknown = Reflect.get(target, property, receiver)
            if (typeof value !== 'function') return value

            const storageMethod = value.bind(target) as (...parameters: unknown[]) => unknown
            if (!STORAGE_SAVE_METHODS.has(property)) return storageMethod

            return (...parameters: unknown[]) => saveStateService.track(async () => (
                await storageMethod(...parameters)
            ))
        },
    })
}

import {
    getElectronCodexRuntimeBridge,
    type CodexUpdateRequired,
    type ElectronCodexRuntimeBridge,
} from '../../data/electron_codex_runtime_bridge'
import { dialogService, type DialogService } from '../dialog_service'
import { register } from '../service_injector'

type CodexRuntimeBridgeProvider = () => ElectronCodexRuntimeBridge | null

/** Owns renderer-wide Codex update warnings and update requests. */
export class CodexCliUpdateService {
    private bridge: ElectronCodexRuntimeBridge | null = null
    private readonly bridgeProvider: CodexRuntimeBridgeProvider
    private readonly dialogs: DialogService
    private unsubscribeUpdateRequired: (() => void) | null = null

    constructor(
        bridgeProvider: CodexRuntimeBridgeProvider = getElectronCodexRuntimeBridge,
        dialogs: DialogService = dialogService,
    ) {
        this.bridgeProvider = bridgeProvider
        this.dialogs = dialogs
        register('codexCliUpdateService', this)
    }

    start() {
        const bridge = this.bridgeProvider()
        if (bridge === this.bridge && this.unsubscribeUpdateRequired) return

        this.stop()
        this.bridge = bridge
        if (!bridge?.onCodexUpdateRequired || !bridge.updateCodexCli) return

        this.unsubscribeUpdateRequired = bridge.onCodexUpdateRequired((update) => this.handleUpdateRequired(bridge, update))
    }

    stop() {
        this.unsubscribeUpdateRequired?.()
        this.unsubscribeUpdateRequired = null
        this.bridge = null
    }

    private handleUpdateRequired(bridge: ElectronCodexRuntimeBridge, update: CodexUpdateRequired) {
        if (bridge !== this.bridge) return
        const { cacheVersion, runningVersion } = update
        if (cacheVersion.length === 0 || runningVersion.length === 0) return

        this.dialogs.warning(
            `Codex CLI ${runningVersion} is incompatible with model cache ${cacheVersion}.`,
            {
                action: {
                    callback: () => this.updateCodex(bridge),
                    label: 'Update Codex',
                },
                title: 'Codex update required',
            },
        )
    }

