            {
                from: '.',
                to: '.',
                filter: ['package.json'],
            },
            {
                from: '.',
                to: 'desktop',
                filter: [
                    'main.js',
                    'src/**/*.js',
                    'src/**/*.mjs',
                    'build/md2.ico',
                    '!**/*.test.mjs',
